import { findConflicts } from './src/booking-conflicts.js';
import assert from 'node:assert/strict';

const t = (d, h, m, s) => d + 'T' + String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0') + 'Z';

// R1
for (const bad of [null, 'x', {a:1}, 42]) assert.throws(() => findConflicts(bad), TypeError);
const mk = (id, room, s, e) => ({ id, room, start: s, end: e });
assert.throws(() => findConflicts([mk('', 'R', t('2026-01-01',0,0,0), t('2026-01-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk('a', '', t('2026-01-01',0,0,0), t('2026-01-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk(1, 'R', t('2026-01-01',0,0,0), t('2026-01-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk('a', 'R', '2026-01-01 00:00:00Z', t('2026-01-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk('a', 'R', '2026-01-01T00:00:00', t('2026-01-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk('a', 'R', '2026-02-30T10:00:00Z', t('2026-03-01',1,0,0))]), TypeError);
assert.throws(() => findConflicts([mk('a', 'R', t('2026-01-01',0,0,0), '2026-01-01T24:00:00Z')]), TypeError);

// R2: end == start and end < start
assert.throws(() => findConflicts([mk('a','R',t('2026-01-01',1,0,0),t('2026-01-01',1,0,0))]), RangeError);
assert.throws(() => findConflicts([mk('a','R',t('2026-01-01',2,0,0),t('2026-01-01',1,0,0))]), RangeError);
assert.throws(() => findConflicts([mk('a','R',t('2026-01-01',1,0,0),t('2026-01-01',2,0,0)), mk('a','S',t('2026-01-01',3,0,0),t('2026-01-01',4,0,0))]), TypeError);

// R3: first problem in order — bad end on booking 1 beats dup id on booking 2
assert.throws(() => findConflicts([mk('a','R',t('2026-01-01',2,0,0),t('2026-01-01',1,0,0)), mk('a','S',t('2026-01-01',3,0,0),t('2026-01-01',4,0,0))]), RangeError);
// R3: R1 field order — bad id on booking 2 beats bad room on booking 3
assert.throws(() => findConflicts([mk('a','R',t('2026-01-01',1,0,0),t('2026-01-01',2,0,0)), mk(7,'R',t('2026-01-01',3,0,0),t('2026-01-01',4,0,0)), mk('b','',t('2026-01-01',5,0,0),t('2026-01-01',6,0,0))]), TypeError);

// R4: touching ranges do not conflict; case-sensitive rooms; identical + contained conflict
assert.deepEqual(findConflicts([
  mk('b','R1',t('2026-03-01',10,0,0),t('2026-03-01',11,0,0)),
  mk('a','R1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)),
]), []);
assert.deepEqual(findConflicts([
  mk('a','A1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)),
  mk('b','a1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)),
]), []);
assert.deepEqual(findConflicts([
  mk('a','R1',t('2026-03-01',9,0,0),t('2026-03-01',12,0,0)),
  mk('b','R1',t('2026-03-01',9,30,0),t('2026-03-01',10,0,0)),
  mk('c','R1',t('2026-03-01',9,0,0),t('2026-03-01',12,0,0)),
]), [['a','b'],['a','c'],['b','c']]);

// R5: sorting by idA then idB; empty
assert.deepEqual(findConflicts([]), []);
assert.deepEqual(findConflicts([
  mk('z','R1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)),
  mk('a','R1',t('2026-03-01',9,30,0),t('2026-03-01',11,0,0)),
  mk('m','R1',t('2026-03-01',10,0,0),t('2026-03-01',12,0,0)),
  mk('a2','R1',t('2026-03-01',9,30,0),t('2026-03-01',11,0,0)),
]).length, 6); // a<a2<z... all 6 pairs among {a,a2,m,z}: a-m? no wait a2-m yes, a-m? a(9:30-11) & m(10-12) yes
// explicit pair ordering
assert.deepEqual(findConflicts([
  mk('b','R1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)),
  mk('a','R1',t('2026-03-01',9,30,0),t('2026-03-01',11,0,0)),
  mk('c','R1',t('2026-03-01',10,0,0),t('2026-03-01',12,0,0)),
]), [['a','b'],['a','c']]);

// R6: no mutation
const arr = [mk('a','R1',t('2026-03-01',9,0,0),t('2026-03-01',10,0,0)), mk('b','R1',t('2026-03-01',9,30,0),t('2026-03-01',11,0,0))];
const before = JSON.stringify(arr);
findConflicts(arr);
assert.equal(JSON.stringify(arr), before);

// valid leap second-free edge: 2026-02-28 valid, 2024-02-29 valid, 2025-02-29 invalid
assert.deepEqual(findConflicts([mk('a','R',t('2024-02-29',1,0,0),t('2024-02-29',2,0,0))]), []);
assert.throws(() => findConflicts([mk('a','R',t('2025-02-29',1,0,0),t('2025-03-01',2,0,0))]), TypeError);

console.log('all sanity checks passed');
"

